"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import {
  DndContext,
  DragOverlay,
  KeyboardSensor,
  MouseSensor,
  TouchSensor,
  closestCorners,
  defaultDropAnimationSideEffects,
  useDndMonitor,
  useSensor,
  useSensors,
  type Announcements,
  type DragEndEvent,
  type DragOverEvent,
  type DragStartEvent,
} from "@dnd-kit/core";
import { arrayMove, sortableKeyboardCoordinates } from "@dnd-kit/sortable";
import { useSelectionContainer, boxesIntersect, type Box } from "@air/react-drag-to-select";
import { motion, useReducedMotion, useSpring } from "motion/react";
import { EASE_POUSO_CSS } from "@/lib/motion";
import { cn } from "@/lib/utils";
import { KanbanColumn } from "./KanbanColumn";
import type { KanbanItem, KanbanProps } from "./types";
import "./kanban.css";

/**
 * Kanban primitive — headless, data-agnostic, dirigido por design tokens.
 *
 * DnD robusto via dnd-kit (Pointer + Touch + Keyboard sensors, DragOverlay,
 * multi-container sortable): substitui o HTML5 drag nativo (sem touch, ghost
 * feio, casos de borda bugados). Reordena dentro da coluna E move entre colunas.
 *
 * Theming: lê só `--kanban-*` (com fallback pros tokens do design system) — troca
 * o arquivo de tokens da marca e o mesmo componente se veste. Ver kanban.css.
 *
 * Seleção múltipla (opt-in via `selectable`): marquee "select by area" (arrastar
 * sobre o vazio, via @air/react-drag-to-select) + shift/ctrl/cmd-clique. O marquee
 * não inicia sobre um card (é alça de drag) nem sobre controles. Emite
 * `onSelectionChange`; a UI de batch é do consumidor. Só ativa com `enabled`.
 *
 * Distribuição: registry estilo shadcn — copia `components/ui/kanban/*` pro
 * projeto do cliente e tematiza pelos tokens. Não conhece Linear/Supabase/auth.
 */
/*
 * O pouso do card — o imã, e o fim do pulo ao soltar.
 *
 * O `DragOverlay` estava sem configuração, então rodava o padrão da lib: 250ms
 * de `ease`, e um efeito colateral que zera a opacidade do card de origem
 * durante a viagem e a devolve de uma vez no fim. Dois problemas nisso:
 *
 * 1. O tempo e a curva vinham de dentro do node_modules. Um encaixe é uma
 *    aterrissagem: `--dur-base` e `--ease-out`, que é como tudo o mais nesta
 *    casa desacelera ao chegar.
 * 2. O card de destino voltava do nada pro opaco no frame em que o overlay
 *    sumia. O buraco agora continua desenhado durante a viagem inteira, e quem
 *    avisa o fim é o `sideEffects`: o overlay some e o card fica inteiro no mesmo
 *    quadro. Sem fade na volta: os dois estão no mesmo pixel, então a troca é
 *    invisível, e um fade ali deixava o card apagado depois do pouso.
 *
 * O tempo e a curva são LIDOS do CSS em vez de escritos aqui. A drop animation
 * é WAAPI, e a Web Animations API não aceita `var(--ease-out)` — mas ela aceita
 * a string que a variável guarda. Então a fonte da verdade continua sendo o
 * arquivo de tokens: quem trocar `--dur-base` na marca troca também o pouso do
 * card, sem abrir este arquivo.
 *
 * Quem pediu menos movimento recebe duração zero: o dnd-kit pula a animação
 * (`if (!duration) return`) e o card simplesmente ESTÁ no destino. O resultado
 * acontece, só não há percurso — e essa é a única forma de alcançar isto, já
 * que o guard global de `prefers-reduced-motion` só enxerga transição CSS.
 */
/** O cartão na mão: inclina um grau parado e até seis no embalo, com mola. */
const INCLINA_PARADO = -1;
const INCLINA_TETO = 6;
const INCLINA_POR_VELOCIDADE = 5;
const MOLA_INCLINA = { stiffness: 320, damping: 22, mass: 0.6 };

/**
 * O cartão que voa inclina na direção do gesto e volta a assentar quando a mão para.
 * A rotação fica neste nó, nunca no de fora: é o de fora que o dnd-kit mede para pousar.
 */
function CartaoNaMao({ children }: { children: React.ReactNode }) {
  const reduzir = useReducedMotion();
  const inclina = useSpring(reduzir ? 0 : INCLINA_PARADO, MOLA_INCLINA);
  const ultimo = useRef({ x: 0, t: 0 });
  const calma = useRef<ReturnType<typeof setTimeout> | null>(null);
  const parar = (alvo: number) => {
    if (calma.current) clearTimeout(calma.current);
    if (!reduzir) inclina.set(alvo);
  };
  useEffect(() => () => { if (calma.current) clearTimeout(calma.current); }, []);
  useDndMonitor({
    onDragMove: ({ delta }) => {
      if (reduzir) return;
      const agora = performance.now();
      const dt = Math.max(8, agora - ultimo.current.t);
      const v = (delta.x - ultimo.current.x) / dt;
      ultimo.current = { x: delta.x, t: agora };
      inclina.set(Math.max(-INCLINA_TETO, Math.min(INCLINA_TETO, INCLINA_PARADO + v * INCLINA_POR_VELOCIDADE)));
      if (calma.current) clearTimeout(calma.current);
      calma.current = setTimeout(() => inclina.set(INCLINA_PARADO), 90);
    },
    onDragEnd: () => parar(0),
    onDragCancel: () => parar(0),
  });
  return (
    <motion.div className="kanban-card-overlay" style={{ rotate: inclina }}>
      {children}
    </motion.div>
  );
}

// Sem anotar `: DropAnimation`: aquele tipo é uma união que inclui a forma
// "função", e por ela o `duration` some — e o guard de pouso abaixo precisa ler
// essa duração. O objeto inferido continua sendo aceito pelo DragOverlay.
function readDropAnimation(aoPousar: () => void) {
  const css = typeof window === "undefined" ? null : getComputedStyle(document.documentElement);
  const token = (name: string, fallback: string) =>
    (css?.getPropertyValue(name).trim() || "") || fallback;

  const raw = token("--dur-slow", "300ms");
  const ms = raw.endsWith("ms") ? parseFloat(raw) : parseFloat(raw) * 1000;
  const reduzido =
    typeof window !== "undefined" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  // A sombra assenta enquanto o card desce (`.kanban-pousando` no kanban.css).
  const assentar = defaultDropAnimationSideEffects({
    className: { dragOverlay: "kanban-pousando" },
  });

  return {
    duration: reduzido ? 0 : Number.isFinite(ms) ? ms : 300,
    easing: EASE_POUSO_CSS,
    sideEffects: (args: Parameters<typeof assentar>[0]) => {
      const desfazer = assentar(args);
      return () => {
        desfazer?.();
        aoPousar();
      };
    },
  };
}

/* Sem isto o leitor de tela anuncia em inglês o id interno ("Draggable item a was dropped"). */
const AVISOS: Announcements = {
  onDragStart: () => "Cartão pego.",
  // Sobre o próprio lugar não há o que dizer: o dnd-kit dispara isto ao pegar, e o
  // aviso atropelava o "Cartão pego." no mesmo instante.
  onDragOver: ({ active, over }) =>
    over?.id === active.id ? undefined : over ? "Cartão sobre uma nova posição." : "Cartão fora das colunas.",
  onDragEnd: ({ over }) => (over ? "Cartão solto." : "Cartão devolvido."),
  onDragCancel: () => "Movimento cancelado. Cartão devolvido.",
};
const INSTRUCOES = {
  draggable: "Espaço pega o cartão. As setas movem. Espaço solta e Esc cancela. No toque, segure e arraste.",
};

export function Kanban<T = unknown, C = unknown>({
  columns,
  items,
  renderCard,
  renderColumnHeader,
  renderColumnEmpty,
  onMove,
  enabled = true,
  selectable = false,
  selectedIds,
  onSelectionChange,
  className,
  columnClassName,
}: KanbanProps<T, C>) {
  const itemById = useMemo(() => {
    const m = new Map<string, KanbanItem<T>>();
    for (const it of items) m.set(it.id, it);
    return m;
  }, [items]);

  const colMeta = useMemo(() => new Map(columns.map((c) => [c.id, c])), [columns]);

  // Fim real do pouso: quem manda é a animação; o relógio de `aguardaPouso` é só a
  // rede para quando ela nem roda (duração zero, overlay já fora da tela).
  const aoPousarRef = useRef<() => void>(() => {});

  // Uma vez por board: a config precisa ser a MESMA referência entre renders,
  // senão o dnd-kit refaz o handler de pouso no meio do gesto e a animação sai
  // pela metade. `[]` de propósito.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const dropAnimation = useMemo(() => readDropAnimation(() => aoPousarRef.current()), []);

  // Ordem vinda das props (a fonte da verdade do consumidor).
  const fromProps = useMemo(() => {
    const map: Record<string, string[]> = {};
    for (const c of columns) map[c.id] = [];
    for (const it of items) (map[it.columnId] ??= []).push(it.id);
    return map;
  }, [columns, items]);

  // Cópia de trabalho — mutável durante o arraste pro card "seguir" pra coluna
  // nova ao vivo; ressincroniza com as props quando não está arrastando.
  const [ordered, setOrdered] = useState<Record<string, string[]>>(fromProps);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [overColumn, setOverColumn] = useState<string | null>(null);
  const fromColumnRef = useRef<string | null>(null);
  // Índice de origem congelado no dragStart: comparar com fromProps atual dava
  // falso-positivo/negativo se um refetch (realtime) chegasse durante o drag.
  const fromIndexRef = useRef<number>(-1);

  /*
   * A ressincronização espera o card POUSAR.
   *
   * O efeito abaixo devolve a ordem das props assim que o gesto acaba — e o
   * gesto acaba no instante do `mouseup`, enquanto o overlay ainda tem a viagem
   * inteira pela frente. Um consumidor que aplique o `onMove` com qualquer
   * diferença (o caso comum: guardar a coluna e ignorar o `columnOrder`) fazia o
   * card SALTAR de volta debaixo do overlay que ainda estava descendo. Ir e
   * voltar num piscar, com o fantasma ainda no ar.
   *
   * Segurar a ressincronização pela duração do pouso resolve pra todo mundo, e
   * não só pra quem escreve o consumidor certo: o card encosta no lugar, e só
   * então a verdade das props volta a mandar. Se ela discordar, a correção
   * aparece — mas aparece sozinha, à vista, e não escondida sob uma animação.
   */
  const [pousando, setPousando] = useState<string | null>(null);
  const [fantasma, setFantasma] = useState<{ escala: number; largura: number } | null>(null);
  const pousoRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const terminaPouso = useCallback(() => {
    if (pousoRef.current) clearTimeout(pousoRef.current);
    setPousando(null);
  }, []);
  aoPousarRef.current = terminaPouso;
  const aguardaPouso = useCallback(
    (id: string) => {
      if (pousoRef.current) clearTimeout(pousoRef.current);
      setPousando(id);
      const duracao = dropAnimation.duration ?? 0;
      pousoRef.current = setTimeout(terminaPouso, duracao ? duracao + 120 : 0);
    },
    [dropAnimation.duration, terminaPouso],
  );
  useEffect(() => () => void (pousoRef.current && clearTimeout(pousoRef.current)), []);

  useEffect(() => {
    if (!activeId && !pousando) setOrdered(fromProps);
  }, [fromProps, activeId, pousando]);

  const sensors = useSensors(
    // MouseSensor, NÃO PointerSensor: Pointer Events incluem touch — com
    // `distance: 6`, qualquer pan de 6px no dedo virava drag IMEDIATO, sem
    // delay (o TouchSensor abaixo nem chegava a decidir). Mouse: um CLIQUE
    // (abrir o card) só vira arraste depois de mover alguns px.
    useSensor(MouseSensor, { activationConstraint: { distance: 6 } }),
    // Touch: long-press deliberado (250ms parado) inicia o drag; mover o dedo
    // além da tolerância durante a espera = é scroll, cancela o drag.
    useSensor(TouchSensor, { activationConstraint: { delay: 250, tolerance: 8 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  // --- Seleção múltipla (opt-in via `selectable`, só faz efeito com `enabled`) --
  const selectionActive = enabled && selectable;
  const controlled = selectedIds != null;
  const [internalSel, setInternalSel] = useState<string[]>([]);
  const selection = controlled ? selectedIds! : internalSel;
  const selSet = useMemo(() => new Set(selection), [selection]);
  // Espelho sempre-atual da seleção pros callbacks do marquee (que não re-assinam).
  const selSetRef = useRef(selSet);
  selSetRef.current = selSet;

  const commitSelection = useCallback(
    (next: string[]) => {
      if (!controlled) setInternalSel(next);
      onSelectionChange?.(next);
    },
    [controlled, onSelectionChange]
  );

  const toggleSelect = useCallback(
    (id: string) => {
      const next = new Set(selSetRef.current);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      commitSelection([...next]);
    },
    [commitSelection]
  );

  // Callback ref (via state) — o marquee precisa do elemento no render pra ancorar
  // os listeners (mousedown/move) só no board, não no document inteiro.
  const [boardEl, setBoardEl] = useState<HTMLDivElement | null>(null);
  // Base congelada no início do gesto: seleção pré-existente se aditivo (shift),
  // senão vazia. O marquee soma os hits a essa base.
  const marqueeBaseRef = useRef<Set<string>>(new Set());

  // Hit-test: quais cards (por data-kanban-card-id) intersectam a caixa do marquee.
  // A lib entrega a `box` em coords RELATIVAS ao container (`.kanban-root`), então
  // convertemos os rects dos cards (viewport) subtraindo o rect do board.
  const hitsInBox = useCallback(
    (box: Box): string[] => {
      if (!boardEl) return [];
      const base = boardEl.getBoundingClientRect();
      const hits: string[] = [];
      boardEl.querySelectorAll<HTMLElement>("[data-kanban-card-id]").forEach((el) => {
        const r = el.getBoundingClientRect();
        const rel = {
          left: r.left - base.left,
          top: r.top - base.top,
          width: r.width,
          height: r.height,
        };
        if (boxesIntersect(box, rel)) {
          const id = el.dataset.kanbanCardId;
          if (id) hits.push(id);
        }
      });
      return hits;
    },
    [boardEl]
  );

  const { DragSelection } = useSelectionContainer<HTMLDivElement>({
    isEnabled: selectionActive,
    eventsElement: boardEl,
    // Não iniciar sobre um card (é alça de drag do dnd-kit) nem sobre controles.
    shouldStartSelecting: (target) => {
      if (!(target instanceof Element)) return false;
      if (target.closest("[data-kanban-card-id]")) return false;
      return !target.closest(
        "button, a, input, textarea, select, [role='button'], [contenteditable='true']"
      );
    },
    onSelectionStart: (e) => {
      const additive = e.shiftKey || e.metaKey || e.ctrlKey;
      marqueeBaseRef.current = additive ? new Set(selSetRef.current) : new Set();
      // Clique no vazio (sem aditivo) limpa a seleção — comportamento Finder/Linear.
      if (!additive && selSetRef.current.size) commitSelection([]);
    },
    onSelectionChange: (box) => {
      const next = new Set(marqueeBaseRef.current);
      for (const id of hitsInBox(box)) next.add(id);
      commitSelection([...next]);
    },
    selectionProps: {
      style: {
        // Cor completa via --kanban-accent (portável entre HSL e OKLCH); ver kanban.css.
        border: "1px solid var(--kanban-accent, oklch(0.62 0.02 240))",
        background: "color-mix(in oklch, var(--kanban-accent, oklch(0.62 0.02 240)) 12%, transparent)",
        borderRadius: "4px",
      },
    },
  });

  // Esc limpa a seleção.
  useEffect(() => {
    if (!selectionActive || selection.length === 0) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") commitSelection([]);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [selectionActive, selection.length, commitSelection]);

  const columnOf = (id: string): string | undefined => {
    if (id in ordered) return id;
    return Object.keys(ordered).find((col) => ordered[col]!.includes(id));
  };

  const itemsOf = (colId: string): KanbanItem<T>[] =>
    (ordered[colId] ?? []).map((id) => itemById.get(id)).filter(Boolean) as KanbanItem<T>[];

  const activeItem = activeId ? itemById.get(activeId) ?? null : null;

  // Board somente-leitura: render simples sem DnD (ex.: board do cliente).
  if (!enabled) {
    return (
      <div className={cn("kanban-root flex", className)}>
        {columns.map((col) => (
          <KanbanColumn
            key={col.id}
            column={col}
            items={(fromProps[col.id] ?? [])
              .map((id) => itemById.get(id))
              .filter(Boolean) as KanbanItem<T>[]}
            enabled={false}
            isOver={false}
            render={renderCard}
            renderHeader={renderColumnHeader}
            renderEmpty={renderColumnEmpty}
            className={columnClassName}
          />
        ))}
      </div>
    );
  }

  const handleDragStart = (e: DragStartEvent) => {
    const id = String(e.active.id);
    setActiveId(id);
    medirFantasma(id);
    // O dedo não vê o cartão por baixo dele: o toque curto confirma que pegou.
    // iOS ignora, e tudo bem: lá sobra a sombra subindo.
    if (typeof TouchEvent !== "undefined" && e.activatorEvent instanceof TouchEvent) {
      navigator.vibrate?.(8);
    }
    const col = columnOf(id) ?? null;
    fromColumnRef.current = col;
    fromIndexRef.current = col ? (ordered[col] ?? []).indexOf(id) : -1;
  };

  /*
   * Board dentro de um `transform: scale` (vitrine, card, modal animando): o
   * fantasma vai pro `body` e perderia a escala, e o cartão saltava de tamanho ao
   * ser levantado. A escala medida na largura do cartão volta num invólucro, por
   * fora do nó com a sombra, e o dedo continua movendo em pixel de tela. Fora de
   * um palco escalado isto é nulo.
   */
  const medirFantasma = (id: string) => {
    const el = boardEl?.querySelector<HTMLElement>(`[data-kanban-card-id="${CSS.escape(id)}"]`);
    const largura = el?.offsetWidth ?? 0;
    const escala = largura ? el!.getBoundingClientRect().width / largura : 1;
    setFantasma(Math.abs(escala - 1) > 0.01 ? { escala, largura } : null);
  };

  const handleDragOver = (e: DragOverEvent) => {
    const active = String(e.active.id);
    const overId = e.over ? String(e.over.id) : null;
    if (!overId) {
      setOverColumn(null);
      return;
    }
    const activeCol = columnOf(active);
    const overCol = columnOf(overId);
    if (!activeCol || !overCol) return;
    if (colMeta.get(overCol)?.dropDisabled) {
      setOverColumn(null);
      return;
    }
    setOverColumn(overCol);
    if (activeCol === overCol) return;

    // Cross-container: insere o card na coluna de destino ao vivo.
    setOrdered((prev) => {
      const activeItems = prev[activeCol] ?? [];
      const overItems = prev[overCol] ?? [];
      if (!activeItems.includes(active)) return prev;
      const overIndex = overId in prev ? overItems.length : overItems.indexOf(overId);
      const insertAt = overIndex >= 0 ? overIndex : overItems.length;
      return {
        ...prev,
        [activeCol]: activeItems.filter((id) => id !== active),
        [overCol]: [...overItems.slice(0, insertAt), active, ...overItems.slice(insertAt)],
      };
    });
  };

  // ESC / cancelamento de sensor dispara onDragCancel, NÃO onDragEnd. Sem este
  // handler o activeId nunca zerava: overlay preso, resync com as props
  // bloqueado e o card órfão na coluna errada até um remount.
  const handleDragCancel = () => {
    aguardaPouso(activeId ?? "");
    setActiveId(null);
    setOverColumn(null);
    fromColumnRef.current = null;
    fromIndexRef.current = -1;
    setOrdered(fromProps);
  };

  const handleDragEnd = (e: DragEndEvent) => {
    const active = String(e.active.id);
    const overId = e.over ? String(e.over.id) : null;
    const from = fromColumnRef.current;
    aguardaPouso(active);
    setActiveId(null);
    setOverColumn(null);
    fromColumnRef.current = null;

    if (!overId) {
      setOrdered(fromProps);
      return;
    }
    const activeCol = columnOf(active);
    const overCol = columnOf(overId) ?? activeCol;
    if (!activeCol || !overCol || colMeta.get(overCol)?.dropDisabled) {
      setOrdered(fromProps);
      return;
    }

    // Após o dragOver, o item já vive na coluna de destino; aqui só refinamos o
    // índice final (reorder dentro da coluna resolvida).
    const arr = ordered[activeCol] ?? [];
    const oldIndex = arr.indexOf(active);
    // Soltar sobre o corpo da coluna (gap/padding, não um card) mantém a posição
    // da prévia ao vivo — antes forçava o card pro FIM da coluna e persistia uma
    // ordem que o usuário não pediu.
    let newIndex = overId in ordered ? oldIndex : arr.indexOf(overId);
    if (newIndex < 0) newIndex = oldIndex;
    const finalArr =
      oldIndex >= 0 && newIndex >= 0 && oldIndex !== newIndex
        ? arrayMove(arr, oldIndex, newIndex)
        : arr;
    const finalOrdered = { ...ordered, [activeCol]: finalArr };
    setOrdered(finalOrdered);

    const toIndex = finalArr.indexOf(active);
    const originalIndex = fromIndexRef.current;
    fromIndexRef.current = -1;
    // Só reporta mudança real (evita write fantasma ao soltar no mesmo lugar).
    if (from !== activeCol || toIndex !== originalIndex) {
      onMove?.({
        itemId: active,
        fromColumnId: from ?? activeCol,
        toColumnId: activeCol,
        toIndex,
        columnOrder: finalArr,
      });
    }
  };

  /*
   * O CARD QUE VOAVA PRA LONGE DO CURSOR — e por que era o pai, não o dnd-kit.
   *
   * O `DragOverlay` é `position: fixed`, e o dnd-kit escreve nele um
   * `translate3d` em coordenadas de VIEWPORT (o rect que ele mediu no início do
   * gesto, mais o delta do ponteiro). Isso só bate enquanto o bloco contenedor
   * do `fixed` for o viewport.
   *
   * Qualquer ancestral com `transform`, `filter`, `perspective`, `backdrop-filter`
   * ou `will-change` dessas propriedades passa a ser o bloco contenedor de
   * descendentes `fixed` — regra do CSS, não bug de lib. Aí o mesmo
   * `translate3d(x, y)` deixa de ser medido do canto da janela e passa a ser
   * medido do canto DAQUELE elemento: o card aparece deslocado exatamente pela
   * posição do ancestral na página (com a rolagem inteira somada, o que numa
   * página longa joga o card pra fora da tela). Ao soltar, o overlay some e o
   * card real reaparece no lugar certo — daí a leitura de "pula pro lugar".
   *
   * Isso não é caso de laboratório: um card com `transform: scale()` pra caber
   * numa vitrine, um painel com `backdrop-filter`, um modal com animação de
   * entrada — todos produzem o mesmo defeito no projeto de quem instalou.
   *
   * O overlay vai pro `body` por portal. Ele não pertence ao fluxo do board (é
   * um fantasma que voa por cima de tudo), então tirá-lo de lá não muda layout
   * nenhum — e passa a viver onde a matemática do dnd-kit já supunha que ele
   * estava. Os tokens `--kanban-*` que o overlay usa têm fallback no ponto de
   * uso (kanban.css), justamente porque fora do `.kanban-root` não há herança.
   */
  const overlay = (
    <DragOverlay dropAnimation={dropAnimation}>
      {activeItem ? (
        <div style={fantasma ? { width: fantasma.largura, transform: `scale(${fantasma.escala})`, transformOrigin: "top left" } : undefined}>
          <CartaoNaMao>{renderCard({ item: activeItem, overlay: true })}</CartaoNaMao>
        </div>
      ) : null}
    </DragOverlay>
  );

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCorners}
      onDragStart={handleDragStart}
      onDragOver={handleDragOver}
      onDragEnd={handleDragEnd}
      onDragCancel={handleDragCancel}
      accessibility={{ announcements: AVISOS, screenReaderInstructions: INSTRUCOES }}
    >
      {/* data-kanban-dragging: consumidores (via `:has()`) desligam scroll-snap
          durante o drag pra não brigar com o auto-scroll do dnd-kit. */}
      <div
        ref={setBoardEl}
        className={cn("kanban-root flex", selectionActive && "relative", className)}
        data-kanban-dragging={activeId ? "" : undefined}
      >
        {/* Retângulo do marquee — renderizado no topo do container dos cards. */}
        {selectionActive ? <DragSelection /> : null}
        {columns.map((col) => (
          <KanbanColumn
            key={col.id}
            column={col}
            items={itemsOf(col.id)}
            enabled
            isOver={overColumn === col.id}
            landingId={pousando}
            render={renderCard}
            renderHeader={renderColumnHeader}
            renderEmpty={renderColumnEmpty}
            className={columnClassName}
            selectable={selectionActive}
            selectedIds={selSet}
            onSelectToggle={toggleSelect}
          />
        ))}
      </div>
      {typeof document === "undefined" ? overlay : createPortal(overlay, document.body)}
    </DndContext>
  );
}

"use client";

import { useMemo } from "react";
import { useDroppable } from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { cn } from "@/lib/utils";
import { KanbanCard } from "./KanbanCard";
import type { KanbanColumn as Col, KanbanItem, KanbanRenderCardArgs } from "./types";

/**
 * Coluna droppable + SortableContext. Também aceita drop quando vazia (o
 * useDroppable no corpo inteiro), senão colunas sem card não seriam alvo.
 */
export function KanbanColumn<T, C>({
  column,
  items,
  enabled,
  isOver,
  landingId,
  render,
  renderHeader,
  renderEmpty,
  className,
  selectable = false,
  selectedIds,
  onSelectToggle,
}: {
  column: Col<C>;
  items: KanbanItem<T>[];
  enabled: boolean;
  isOver: boolean;
  /** Cartão ainda pousando: segue como buraco até o fantasma chegar. */
  landingId?: string | null;
  render: (args: KanbanRenderCardArgs<T>) => React.ReactNode;
  renderHeader?: (column: Col<C>) => React.ReactNode;
  renderEmpty?: (column: Col<C>) => React.ReactNode;
  className?: string;
  selectable?: boolean;
  selectedIds?: Set<string>;
  onSelectToggle?: (id: string) => void;
}) {
  const droppable = enabled && !column.dropDisabled;
  const { setNodeRef } = useDroppable({ id: column.id, disabled: !droppable });

  // A MESMA referência enquanto a ordem não muda. O sortable compara os itens por
  // referência: array novo a cada render lia como "a lista mudou" e desligava o
  // deslize de todos os cartões, em todo render.
  const idsKey = items.map((i) => i.id).join("\n");
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const ids = useMemo(() => items.map((i) => i.id), [idsKey]);

  return (
    <div
      className={cn(
        "kanban-column flex flex-col",
        isOver && droppable && "is-drop-target",
        className
      )}
    >
      {renderHeader?.(column)}
      <SortableContext
        items={ids}
        strategy={verticalListSortingStrategy}
      >
        <div ref={setNodeRef} className="kanban-column-body flex-1">
          {items.length === 0
            ? renderEmpty?.(column)
            : items.map((item) => (
                <KanbanCard
                  key={item.id}
                  item={item}
                  enabled={enabled}
                  landing={landingId === item.id}
                  render={render}
                  selectable={selectable}
                  selected={selectedIds?.has(item.id) ?? false}
                  onSelectToggle={onSelectToggle}
                />
              ))}
        </div>
      </SortableContext>
    </div>
  );
}

"use client";

import {
  defaultAnimateLayoutChanges,
  useSortable,
  type AnimateLayoutChanges,
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { cn } from "@/lib/utils";
import type { KanbanItem, KanbanRenderCardArgs } from "./types";

/*
 * Vizinhos deslizam também quando o cartão muda de coluna. O padrão da lib só anima
 * quem acabou de ser arrastado: ao entrar numa coluna, os de baixo saltavam 93px de
 * um quadro para o outro, enquanto dentro da coluna tudo deslizava.
 */
const animarVizinhos: AnimateLayoutChanges = (args) =>
  defaultAnimateLayoutChanges({ ...args, wasDragging: true });

/**
 * Card arrastável (useSortable). O card inteiro é a alça — a distância de
 * ativação do sensor (no <Kanban>) garante que um CLIQUE simples ainda passe
 * para o onClick do conteúdo; só vira arraste depois de mover alguns px.
 */
export function KanbanCard<T>({
  item,
  enabled,
  landing = false,
  render,
  selectable = false,
  selected = false,
  onSelectToggle,
}: {
  item: KanbanItem<T>;
  enabled: boolean;
  /** O fantasma ainda está descendo até aqui. */
  landing?: boolean;
  render: (args: KanbanRenderCardArgs<T>) => React.ReactNode;
  /** Seleção múltipla ligada — habilita o shift/ctrl/cmd-clique de toggle. */
  selectable?: boolean;
  selected?: boolean;
  onSelectToggle?: (id: string) => void;
}) {
  const {
    setNodeRef,
    attributes,
    listeners,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: item.id, disabled: !enabled, animateLayoutChanges: animarVizinhos });

  // O tempo e a curva do deslize moram em `.kanban-card` (kanban.css), nos tokens da
  // casa. Mas a lib também usa `transition` para DESLIGAR: `0ms` no quadro em que ela
  // reposiciona o cartão sem animar, e nada quando não há o que animar. Ignorar esses
  // dois fazia o CSS animar a correção, e ao soltar o vizinho saltava 93px para cima e
  // voltava deslizando. Era o último flicker do pouso.
  const transicao = !transition ? "none" : transition.includes(" 0ms") ? transition : undefined;

  return (
    <div
      ref={setNodeRef}
      // O marquee (Kanban) acha os cards por este atributo pra calcular o hit-test.
      data-kanban-card-id={item.id}
      data-selected={selectable && selected ? "" : undefined}
      aria-selected={selectable ? selected : undefined}
      style={{ transform: CSS.Translate.toString(transform), transition: transicao }}
      // Modifier-clique = toggle na seleção (não abre o card). Capture pra
      // interceptar ANTES do onClick do conteúdo (render do consumidor).
      onClickCapture={
        selectable
          ? (e) => {
              if (e.shiftKey || e.metaKey || e.ctrlKey) {
                e.preventDefault();
                e.stopPropagation();
                onSelectToggle?.(item.id);
              }
            }
          : undefined
      }
      className={cn(
        // `manipulation`, não `none`: o TouchSensor ativa por delay (150ms) e aí
        // preventDefault nos touchmove — `none` bloqueava o pan nativo que os
        // scrolls mobile (coluna interna + rail snap-x) precisam quando o gesto
        // começa em cima de um card, ou seja, quase sempre.
        "kanban-card touch-manipulation",
        enabled && "kanban-card-movel cursor-grab active:cursor-grabbing",
        // O card de origem vira o ALVO em vez de sumir. Era `opacity-40` aqui —
        // e como a demo pintava outro `.4` no conteúdo, dava 0.16 na tela: o
        // lugar de destino existia e ninguém enxergava. Agora ele se desenha
        // como buraco tracejado (ver `.is-drop-slot` no kanban.css), que é o
        // ponto exato onde o card cai e o que faz o gesto ter imã.
        (isDragging || landing) && "is-drop-slot"
      )}
      {...(enabled ? attributes : {})}
      {...(enabled ? listeners : {})}
    >
      {render({ item, dragging: isDragging, selected: selectable ? selected : undefined })}
    </div>
  );
}

/**
 * Kanban primitive — tipos públicos.
 *
 * Data-agnostic por design: o componente não conhece Linear, Supabase, auth ou
 * "membro". Recebe colunas + itens e emite `onMove`. Quem pluga dado é o
 * consumidor (neste app, o board do time; num projeto de cliente, o que for).
 */
import type { ReactNode } from "react";

export interface KanbanColumn<C = unknown> {
  /** Chave estável da coluna (ex.: um status). */
  id: string;
  /** Dado livre do consumidor (cor, label, contadores…) para o header. */
  data?: C;
  /** Coluna não aceita drops (arrastável PARA fora, mas não é alvo). */
  dropDisabled?: boolean;
}

export interface KanbanItem<T = unknown> {
  /** Id estável do card. */
  id: string;
  /** Coluna a que o card pertence. */
  columnId: string;
  /** Dado livre do consumidor, repassado ao `renderCard`. */
  data: T;
}

export interface KanbanMove {
  itemId: string;
  fromColumnId: string;
  toColumnId: string;
  /** Índice final dentro da coluna de destino. */
  toIndex: number;
  /** Ordem completa (ids) da coluna de destino após o move — pronta pra persistir. */
  columnOrder: string[];
}

export interface KanbanRenderCardArgs<T> {
  item: KanbanItem<T>;
  /** true no overlay de arraste (o card "fantasma" que segue o cursor). */
  overlay?: boolean;
  /** true no card original enquanto ele está sendo arrastado. */
  dragging?: boolean;
  /** true quando o card faz parte da seleção múltipla (ver `selectable`). */
  selected?: boolean;
}

export interface KanbanProps<T = unknown, C = unknown> {
  columns: KanbanColumn<C>[];
  items: KanbanItem<T>[];
  /** Slot obrigatório: o consumidor desenha o card (mantém o core de DnD genérico). */
  renderCard: (args: KanbanRenderCardArgs<T>) => ReactNode;
  /** Slot opcional do cabeçalho da coluna. */
  renderColumnHeader?: (column: KanbanColumn<C>) => ReactNode;
  /** Slot opcional do vazio da coluna. */
  renderColumnEmpty?: (column: KanbanColumn<C>) => ReactNode;
  /**
   * Disparado ao soltar: mover entre colunas E reordenar dentro da mesma. O
   * consumidor persiste (status + ordem) e/ou revalida.
   */
  onMove?: (move: KanbanMove) => void;
  /** DnD ligado. Off = board somente-leitura (ex.: board do cliente). */
  enabled?: boolean;
  /**
   * Liga a seleção múltipla: marquee "select by area" (arrastar sobre o vazio) +
   * shift/ctrl/cmd-clique num card. Só faz efeito com `enabled` (board editável).
   * O consumidor desenha a UI de batch a partir de `onSelectionChange`.
   */
  selectable?: boolean;
  /** Ids selecionados (controlado). Se omitido, o Kanban mantém a seleção interna. */
  selectedIds?: string[];
  /** Notifica a nova seleção — SSoT do consumidor + gatilho da barra de batch. */
  onSelectionChange?: (ids: string[]) => void;
  className?: string;
  /** Classe extra por coluna (largura, etc.). */
  columnClassName?: string;
}

export { Kanban } from "./Kanban";
export type {
  KanbanColumn,
  KanbanItem,
  KanbanMove,
  KanbanProps,
  KanbanRenderCardArgs,
} from "./types";

/*
 * Kanban primitive — tokens + estilos base.
 *
 * TODO visual sai daqui via CSS custom properties `--kanban-*`. Cada token cai
 * primeiro no token equivalente do design system Visant (`--t-*`, `--accent`) e,
 * se ele não existir (projeto de cliente sem o design system Visant), num valor
 * neutro embutido. Trocar a marca = sobrescrever `--kanban-*` (ou `--accent`),
 * nunca o componente.
 */
.kanban-root {
  --kanban-gap: 1rem;
  --kanban-col-min: 280px;
  --kanban-col-max: 480px;
  --kanban-card-gap: 0.75rem;
  --kanban-card-radius: var(--t-card-radius, 0.75rem);
  --kanban-column-radius: var(--t-card-radius, 0.75rem);
  --kanban-column-min-h: 120px;
  /* Accent do realce: UM token de COR COMPLETA que o primitivo consome. Cada app
     seta `--kanban-accent` (qualquer espaço de cor) num wrapper ancestral; o
     default mora no fallback do var(), NO PONTO DE USO. NÃO declarar
     `--kanban-accent` aqui em `.kanban-root`: custom-prop declarada no elemento
     vence a herdada, então o valor do wrapper ancestral seria sombreado e o
     bridge do app não pintaria. NÃO usar `hsl(var(--accent))`: quebra em silêncio
     quando o host guarda --accent como cor oklch em vez de triplet HSL. */
  --kanban-drop-ring: color-mix(in oklch, var(--kanban-accent, oklch(0.62 0.02 240)) 45%, transparent);
  --kanban-drop-bg: color-mix(in oklch, var(--kanban-accent, oklch(0.62 0.02 240)) 8%, transparent);

  display: flex;
  gap: var(--kanban-gap);
  width: 100%;
}

@media (min-width: 640px) {
  .kanban-root {
    --kanban-col-min: 320px;
  }
}

.kanban-column {
  flex: 1 1 0%;
  min-width: var(--kanban-col-min);
  max-width: var(--kanban-col-max);
  border-radius: var(--kanban-column-radius);
  /* Inerte sem um snap container — o wrapper mobile do KanbanBoard liga
     `snap-x`; no desktop (sm:snap-none) isto não faz nada. */
  scroll-snap-align: start;
}

/*
 * A COLUNA NÃO ACENDE MAIS. Era o defeito central do arraste.
 *
 * Antes, passar por cima pintava a coluna inteira de fundo e punha um anel de
 * 2px em volta dela. Isso responde a pergunta errada: a pessoa já sabe sobre
 * qual coluna está o cursor — ela quer saber ONDE o card vai parar, entre quais
 * dois vizinhos. Uma coluna de 500px acesa por causa de um card de 34px é ruído
 * do tamanho da tela, e é exatamente o que fazia o gesto parecer impreciso.
 *
 * O alvo agora é o slot (`.kanban-card.is-drop-slot`, abaixo): o próprio buraco
 * onde o card vai cair, no tamanho e no lugar exatos. A classe fica como gancho
 * pra quem quiser marcar a coluna no projeto do cliente, sem pintura por padrão.
 */
.kanban-column.is-drop-target {
  /* sem pintura — ver comentário acima */
}

.kanban-column-body {
  display: flex;
  flex-direction: column;
  gap: var(--kanban-card-gap);
  min-height: var(--kanban-column-min-h);
}

/* Mobile: a coluna rola internamente (Trello-like) — o header da coluna fica
   sempre visível e uma coluna longa não vira um page-scroll infinito. O dnd-kit
   auto-rola ancestrais scrolláveis, então drag dentro da coluna segue ok.
   Desktop (≥640px) intocado: page scroll como sempre. */
@media (max-width: 639px) {
  .kanban-column-body {
    max-height: calc(100dvh - 15rem);
    overflow-y: auto;
    padding-bottom: 0.25rem;
  }
}

/* Toque: long-press no card é gesto de DRAG (250ms no TouchSensor) — sem
   isto o browser responde primeiro com seleção de texto + callout do iOS e
   quebra o gesto no meio. Mouse mantém seleção normal. */
@media (max-width: 639px), (pointer: coarse) {
  .kanban-card {
    -webkit-user-select: none;
    user-select: none;
    -webkit-touch-callout: none;
  }
}

/*
 * O deslocamento dos vizinhos abrindo espaço, na SSoT da casa.
 *
 * O dnd-kit escrevia `transition: transform 200ms` (e `transform linear` nos
 * vizinhos) direto no atributo style — dois tempos e duas curvas que ninguém
 * desta casa escolheu, e que nenhum arquivo de tokens alcançava. O KanbanCard
 * parou de repassar aquele valor pro style inline e o tempo passou a morar
 * aqui. Curva `out` e tempo longo: o vizinho sai na hora em que o cartão chega e
 * desacelera até o lugar, e um novo gesto pega ele de onde estiver.
 */
.kanban-card {
  transition-property: transform;
  transition-duration: var(--dur-slow, 300ms);
  transition-timing-function: var(--ease-out);

  /*
   * O contorno do slot existe SEMPRE, transparente — e é isso que faz a entrada
   * do buraco ser suave.
   *
   * `outline-style` não é animável: enquanto o repouso era `outline: none`, o
   * tracejado do slot aparecia em um quadro, no meio de um gesto em que todo o
   * resto desliza. Declarado aqui com cor transparente, só a COR muda de estado.
   * `outline` não ocupa espaço, então o card parado continua com a mesma caixa.
   */
  border-radius: var(--kanban-card-radius);
  outline: 1.5px dashed transparent;
  outline-offset: -1px;
  background-color: transparent;
}

/*
 * O foco de teclado. O `outline` do card é do slot (tracejado do encaixe), então
 * o anel de foco mora no `box-shadow` — os dois nunca disputam a mesma
 * propriedade. Sem isto o card focado pelo Tab (o dnd-kit põe `tabindex=0` pra
 * mover pelo teclado) não mostrava onde o foco estava.
 */
.kanban-card:focus-visible {
  box-shadow: var(--focus, 0 0 0 2px var(--background), 0 0 0 4px var(--brand));
}

/*
 * O SLOT: o buraco onde o card vai cair, no lugar exato.
 *
 * Enquanto arrasta, o card de origem já vive na posição de destino (o
 * `onDragOver` move ele ao vivo). Antes ele ficava só com `opacity: .4` — e
 * como a demo aplicava OUTRO `.4` no conteúdo, o resultado real era 0.16:
 * um borrão que não se via. Ou seja, o alvo existia e era invisível; daí a
 * sensação de arrastar sem imã.
 *
 * Agora ele se desenha como um encaixe: contorno tracejado no accent da marca e
 * o conteúdo apagado. `outline`, e não `border`, porque outline não ocupa
 * espaço — o buraco fica com o tamanho EXATO do card, que é a única forma de o
 * overlay pousar em cima dele sem sobrar nem faltar pixel.
 */
.kanban-card.is-drop-slot {
  transition-property: transform, outline-color, background-color;
  outline-color: var(--kanban-drop-ring);
  background-color: var(--kanban-drop-bg);
}

/*
 * O aperto: antes de virar arraste, o cartão responde ao dedo e ao mouse. No toque
 * são 250ms de espera até levantar, e sem isto eles pareciam tela travada. O atraso
 * deixa passar o toque de quem está só rolando a página. A escala fica no conteúdo,
 * nunca no `.kanban-card`: é ele que o dnd-kit mede.
 */
.kanban-card-movel > * {
  transition: transform var(--dur-press, 120ms) var(--ease-out);
}

.kanban-card-movel:active:not(.is-drop-slot) > * {
  transform: scale(0.985);
  transition-delay: 60ms;
}

/*
 * O buraco só anima ao ENTRAR. Ao sair, o fantasma está exatamente em cima dele e
 * os dois trocam de lugar no mesmo quadro: qualquer transição aqui aparece como o
 * cartão aceso pela metade depois de pousado.
 *
 * O buraco fica aceso até o fim do pouso (`landing`, em Kanban.tsx). Ao soltar, o
 * `isDragging` vira false na hora e o fantasma ainda tem a viagem inteira: antes o
 * destino piscava inteiro, apagava e acendia de novo, com dois cartões iguais na tela.
 */
.kanban-card.is-drop-slot > * {
  opacity: 0.12;
  transition: opacity var(--dur-fast, 160ms) var(--ease-out);
}

.kanban-card-overlay {
  cursor: grabbing;
  /* Fallback no ponto de uso, e não herança: o overlay é portalizado no `body`
     (ver a nota do bloco contenedor em Kanban.tsx), então ele não é descendente
     do `.kanban-root` e não alcança nenhum `--kanban-*` declarado lá. */
  border-radius: var(--kanban-card-radius, var(--t-card-radius, 0.75rem));
  /* A sombra é o que diz "este está no ar e os outros no papel". Sem ela o card
     que viaja tem o mesmo peso visual dos parados e o gesto parece um bug de
     render. O anel é a metade que vale no escuro: preto sobre palco escuro não se
     vê, e no toque o cartão levantava sem mudar nada à vista.
     Nada de `scale` aqui: o cartão levanta do tamanho que tem. A inclinação com
     mola vem do `CartaoNaMao`, em Kanban.tsx. */
  box-shadow:
    0 0 0 1px color-mix(in oklch, var(--foreground, black) 16%, transparent),
    0 1px 2px color-mix(in oklch, black 16%, transparent),
    0 16px 32px -8px color-mix(in oklch, black 45%, transparent);
  /* A ENTRADA do gesto. O overlay nascia já com a sombra inteira: o card não era
     "pego", ele aparecia no ar de um quadro pro outro, e o começo do arraste
     ficava com a mesma dureza que o fim tinha antes de o pouso ser animado.
     Agora a sombra CRESCE — o card sobe do papel em vez de já estar em cima.

     Só `box-shadow` anima, e o motivo está no comentário acima: o dnd-kit lê o
     transform computado DESTE nó pra calcular o pouso, então escala ou
     deslocamento nossos entrariam na conta e errariam o alvo. */
  animation: kanban-overlay-erguer var(--dur-base, 200ms)
    var(--ease-out) backwards;
}

/* O pouso: a sombra assenta enquanto o cartão desce, em vez de sumir com ele. */
.kanban-pousando .kanban-card-overlay {
  box-shadow: none;
  transition: box-shadow var(--dur-slow, 300ms) var(--ease-out);
}

@keyframes kanban-overlay-erguer {
  from {
    box-shadow:
      0 0 0 0 transparent,
      0 0 0 transparent,
      0 0 0 -8px transparent;
  }
}

/* Quem pediu menos movimento recebe o resultado, não o percurso — o pouso já é
   zerado no JS (ver `readDropAnimation`), e aqui vai a metade CSS do mesmo
   acordo, pra quem instalar o bloco num projeto sem o guard global da casa. */
@media (prefers-reduced-motion: reduce) {
  .kanban-card {
    transition-duration: 0.001ms;
  }
  .kanban-card > * {
    transition-duration: 0.001ms;
  }
  .kanban-card-movel:active:not(.is-drop-slot) > * {
    transform: none;
  }
  .kanban-card-overlay {
    animation-duration: 0.001ms;
  }
}

/* Card na seleção múltipla — anel no accent da marca (fallback neutro). O ring
   fica no wrapper; o conteúdo (card do consumidor) mantém o próprio raio. */
.kanban-card[data-selected] {
  border-radius: var(--kanban-card-radius);
  box-shadow: 0 0 0 2px var(--kanban-accent, oklch(0.62 0.02 240));
}
